from __future__ import annotations

import unicodedata
import unittest


class NormalizeKeyTests(unittest.TestCase):
    def test_normalize_key_matches_unicodedata_nfc(self) -> None:
        from ledgerlock.format import normalize_key

        for sample in ["hello", "", "café", "Z͑ͫ̓ͪ̂ͫ̽͏̴̙̤̞͉͚̯̞̠͍A̴̵̜̰͔ͫ͗͢L̠̠̘̹ͯ͂͂͗͢G̠̠̹̯͉ͯ͗͢O̢̢̺̜̹ͭ͒͂̃", "💡", "key with spaces"]:
            self.assertEqual(
                normalize_key(sample), unicodedata.normalize("NFC", sample)
            )

    def test_nfc_and_nfd_yield_byte_identical_results(self) -> None:
        from ledgerlock.format import normalize_key

        nfc = "\u00e9"
        nfd = "e\u0301"
        self.assertEqual(normalize_key(nfc), "\u00e9")
        self.assertEqual(normalize_key(nfd), "\u00e9")
        self.assertEqual(normalize_key(nfc), normalize_key(nfd))
        self.assertEqual(
            normalize_key(nfc).encode("utf-8"), normalize_key(nfd).encode("utf-8")
        )


if __name__ == "__main__":
    unittest.main()

